{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01Fd1F7JtMz8jDAXaw6Q9Nsz","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"    def create_envs(self, n_envs: int, use_async_envs: bool = False):\\\\n        from .libero import create_libero_envs\\\\n\\\\n        if self.task is None:\\\\n            raise ValueError(\\\\\\\"LiberoEnv requires a task to be specified\\\\\\\")\\\\n        env_cls = _make_vec_env_cls(use_async_envs, n_envs)\\\\n        return create_libero_envs(\\\\n            task=self.task,\\\\n            n_envs=n_envs,\\\\n            camera_name=self.camera_name,\\\\n            init_states=self.init_states,\\\\n            gym_kwargs=self.gym_kwargs,\\\\n            env_cls=env_cls,\\\\n            control_mode=self.control_mode,\\\\n            episode_length=self.episode_length,\\\\n            camera_name_mapping=self.camera_name_mapping,\\\\n            is_libero_plus=self.is_libero_plus,\\\\n        )\\\\n\\\\n    def get_env_processors(self):\\\\n        return (\\\\n            PolicyProcessorPipeline(steps=[LiberoProcessorStep()]),\\\\n            PolicyProcessorPipeline(steps=[]),\\\\n        )\\\\n\\\\n\\\\n@EnvConfig.register_subclass(\\\\\\\"metaworld\\\\\\\")\\\\n@dataclass\\\\nclass MetaworldEnv(EnvConfig):\\\\n    task: str = \\\\\\\"metaworld-push-v2\\\\\\\"  # add all tasks\\\\n    fps: int = 80\\\\n    episode_length: int = 400\\\\n    obs_type: str = \\\\\\\"pixels_agent_pos\\\\\\\"\\\\n    render_mode: str = \\\\\\\"rgb_array\\\\\\\"\\\\n    multitask_eval: bool = True\\\\n    features: dict[str, PolicyFeature] = field(\\\\n        default_factory=lambda: {\\\\n            \\\\\\\"action\\\\\\\": PolicyFeature(type=FeatureType.ACTION, shape=(4,)),\\\\n        }\\\\n    )\\\\n    features_map: dict[str, str] = field(\\\\n        default_factory=lambda: {\\\\n            \\\\\\\"action\\\\\\\": ACTION,\\\\n            \\\\\\\"agent_pos\\\\\\\": OBS_STATE,\\\\n            \\\\\\\"top\\\\\\\": f\\\\\\\"{OBS_IMAGE}\\\\\\\",\\\\n            \\\\\\\"pixels/top\\\\\\\": f\\\\\\\"{OBS_IMAGE}\\\\\\\",\\\\n        }\\\\n    )\\\\n\\\\n    def __post_init__(self):\\\\n        if self.obs_type == \\\\\\\"pixels\\\\\\\":\\\\n            self.features[\\\\\\\"top\\\\\\\"] = PolicyFeature(type=FeatureType.VISUAL, shape=(480, 480, 3))\\\\n\\\\n        elif self.obs_type == \\\\\\\"pixels_agent_pos\\\\\\\":\\\\n            self.features[\\\\\\\"agent_pos\\\\\\\"] = PolicyFeature(type=FeatureType.STATE, shape=(4,))\\\\n            self.features[\\\\\\\"pixels/top\\\\\\\"] = PolicyFeature(type=FeatureType.VISUAL, shape=(480, 480, 3))\\\\n\\\\n        else:\\\\n            raise ValueError(f\\\\\\\"Unsupported obs_type: {self.obs_type}\\\\\\\")\\\\n\\\\n    @property\\\\n    def gym_kwargs(self) -> dict:\\\\n        return {\\\\n            \\\\\\\"obs_type\\\\\\\": self.obs_type,\\\\n            \\\\\\\"render_mode\\\\\\\": self.render_mode,\\\\n        }\\\\n\\\\n    def create_envs(self, n_envs: int, use_async_envs: bool = False):\\\\n        from .metaworld import create_metaworld_envs\\\\n\\\\n        if self.task is None:\\\\n            raise ValueError(\\\\\\\"MetaWorld requires a task to be specified\\\\\\\")\\\\n        env_cls = _make_vec_env_cls(use_async_envs, n_envs)\\\\n        return create_metaworld_envs(\\\\n            task=self.task,\\\\n            n_envs=n_envs,\\\\n            gym_kwargs=self.gym_kwargs,\\\\n            env_cls=env_cls,\\\\n        )\\\\n\\\\n\\\\n@EnvConfig.register_subclass(\\\\\\\"robocasa\\\\\\\")\\\\n@dataclass\\\\nclass RoboCasaEnv(EnvConfig):\\\\n    task: str = \\\\\\\"CloseFridge\\\\\\\"\\\\n    fps: int = 20\\\\n    episode_length: int = 1000\\\\n    obs_type: str = \\\\\\\"pixels_agent_pos\\\\\\\"\\\\n    render_mode: str = \\\\\\\"rgb_array\\\\\\\"\\\\n    camera_name: str = \\\\\\\"robot0_agentview_left,robot0_eye_in_hand,robot0_agentview_right\\\\\\\"\\\\n    observation_height