():\n    parts = k.rsplit(\".\", 1)\n    if len(parts) == 2:\n        feat, stat = parts\n        if feat not in dataset_stats:\n            dataset_stats[feat] = {}\n        dataset_stats[feat][stat] = v\n\npreprocessor, postprocessor = make_smolvla_pre_post_processors(policy.config, dataset_stats=dataset_stats)\n\n# Environment processors\nenv_preprocessor = PolicyProcessorPipeline(steps=[LiberoProcessorStep()])\nenv_postprocessor = PolicyProcessorPipeline(steps=[])\n\nprint(\"Loading LIBERO object envs...\", flush=True)\nfrom libero.libero import benchmark as bm\nfrom libero.libero.envs import OffScreenRenderEnv\n\nbenchmark_instance = bm.get_benchmark(\"libero_object\")()\nn_tasks = 2  # test first 2 tasks\nn_episodes = 2\nmax_steps = 280\n\nresults = []\nfor task_idx in range(n_tasks):\n    task = benchmark_instance.get_task(task_idx)\n    task_bddl = benchmark_instance.get_task_bddl_file_path(task_idx)\n    init_states = benchmark_instance.get_task_init_states(task_idx)\n    \n    env = OffScreenRenderEnv(\n        bddl_file_name=task_bddl,\n        camera_heights=256,\n        camera_widths=256,\n        camera_names=[\"agentview\", \"robot0_eye_in_hand\"],\n    )\n    env.seed(42)\n    \n    # Get task description - use same format as LiberoEnv\n    task_desc = task.language\n    print(f\"\\nTask {task_idx}: {task_desc}\", flush=True)\n\n    # Build camera name mapping (same as default LiberoEnv)\n    camera_name_mapping = {\n        \"agentview_image\": \"camera1\",\n        \"robot0_eye_in_hand_image\": \"camera2\",\n    }\n\n    for ep_idx in range(n_episodes):\n        env.reset()\n        obs = env.set_init_state(init_states[ep_idx])\n        policy.reset()\n\n        t0 = time.time()\n        for step in range(max_steps):\n            # Build raw gym-style observation (mimic LiberoEnv._format_raw_obs)\n            images = {}\n            for cam in [\"agentview_image\", \"robot0_eye_in_hand_image\"]:\n                images[camera_name_mapping[cam]] = obs[cam]\n            \n            eef_pos = obs.get(\"robot0_eef_pos\")\n            eef_quat = obs.get(\"robot0_eef_quat\")\n            eef_mat = env.robots[0].controller.ee_ori_mat\n            gripper_qpos = obs.get(\"robot0_gripper_qpos\")\n            gripper_qvel = obs.get(\"robot0_gripper_qvel\")\n            joint_pos = obs.get(\"robot0_joint_pos\")\n            joint_vel = obs.get(\"robot0_joint_vel\")\n            \n            raw_obs = {\n                \"pixels\": images,\n                \"robot_state\": {\n                    \"eef\": {\"pos\": eef_pos, \"quat\": eef_quat, \"mat\": eef_mat},\n                    \"gripper\": {\"qpos\": gripper_qpos, \"qvel\": gripper_qvel},\n                    \"joints\": {\"pos\": joint_pos, \"vel\": joint_vel},\n                },\n            }\n\n            # Step 1: preprocess_observation (numpy -> tensor, rename keys)\n            processed_obs = preprocess_observation(raw_obs)\n            \n            # Step 2: Add task description\n            processed_obs[\"task\"] = [task_desc]\n            \n            # Step 3: env_preprocessor (LiberoProcessorStep - flip images, flatten state)\n            processed_obs = env_preprocessor(processed_obs)\n            \n            # Step 4: policy preprocessor (rename, batch, newline, tokenize, device, normalize)\n            processed_obs = preprocessor(processed_obs)\n            \n            # Step 5: select_action (returns normalized action)\n            with torch.inference_mode():\n                action = policy.select_action(processed_obs)\n            \n            # Step 6: postprocessor (unnormalize action)\n            action = postprocessor(action)\n            \n            # Step 7: to numpy\n            action_np = action.to(\"cpu\").numpy().squeeze()\n            \n            # Step 8: env step\n            obs, reward, done, info = env.step(action_np)\n            \n            success = env.check_success()\n            if success:\n                break\n        \n        elapsed = time.time() - t0\n        result = {\n            \"task\": task_desc,\n            \"episode\": ep_idx,\n            \"success\": bool(success),\n            \"steps\": step + 1,\n            \"time\": round(elapsed, 1),\n        }\n        results.append(result)\n        print(json.dumps(result), flush=True)\n    \n    env.close()\n\nn_success = sum(r[\"success\"] for r in results)\nprint(f\"\\n{'='*60}\", flush=True)\nprint(f\"Results: {n_success}/{len(results)} success ({100*n_success/len(results):.0f}%)\", flush=True)\nPYEOF\necho \"Script written.\""},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":3056,"cache_read_input_tokens":113256,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":3056},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"2e5005b7-4383-4494-8f3b-f04ce9f94618","uuid":"664242a2-585f-47f1-83cd-fc32222a61bb"}
